from __future__ import annotations

import base64
import gzip
import subprocess
from pathlib import Path

EXPECTED = {
    "open-model-market/openrouter_api.py": "5014f173112b760498839718c2abe791abc14bb7",
    "open-model-market/v5_runtime.py": "d0fb82e49b276cca411f8cdcb5c9c1d90349f6db",
    "open-model-market/v5_task_constraints.py": "9f713ba0ea820370645b29fae05f6e525edff44b",
    "tests/test_v5_quantity_binding_context.py": "bbc022651559f8350823af1142d87ffc9bd2a18c",
}
NEW_FILES = (
    "tests/test_openrouter_response_protocol.py",
    "tests/test_v5_response_diagnostics_evidence.py",
)
PAYLOAD = ""


def main() -> None:
    for path, expected in EXPECTED.items():
        actual = subprocess.check_output(["git", "hash-object", path], text=True).strip()
        if actual != expected:
            raise SystemExit(f"unexpected base blob for {path}: {actual} != {expected}")
    for path in NEW_FILES:
        if Path(path).exists():
            raise SystemExit(f"new test path already exists: {path}")
    patch = gzip.decompress(base64.b64decode(PAYLOAD))
    patch_path = Path(".v5-response-protocol.patch")
    patch_path.write_bytes(patch)
    subprocess.run(["git", "apply", "--check", str(patch_path)], check=True)
    subprocess.run(["git", "apply", str(patch_path)], check=True)
    patch_path.unlink()


if __name__ == "__main__":
    main()
